915\u094d\u092f\u093e ZB-2p \u0915\u093e \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0936\u0942\u0928\u094d\u092f-\u092c\u092c\u0932 (Zero-Bubble) \u0926\u093e\u0935\u093e \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0939\u093e\u0930\u094d\u0921\u0935\u0947\u092f\u0930 \u092a\u0930 \u0938\u0902\u091a\u093e\u0930 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 (P2P latency), \u0915\u0930\u094d\u0928\u0947\u0932 \u0932\u0949\u0928\u094d\u091a \u0913\u0935\u0930\u0939\u0947\u0921, \u0938\u094d\u091f\u0947\u091c \u0905\u0938\u0902\u0924\u0941\u0932\u0928 (stage skew), \u0914\u0930 \u092e\u0947\u092e\u094b\u0930\u0940 \u0915\u0902\u091f\u0947\u0902\u0936\u0928 \u0915\u0940 \u0909\u092a\u0938\u094d\u0925\u093f\u0924\u093f \u092e\u0947\u0902 \u092d\u0940 \u0916\u0930\u093e \u0909\u0924\u0930\u0924\u093e \u0939\u0948 \u092f\u093e \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u092c\u092c\u0932 \u0930\u0947\u091f \u092e\u0947\u0902 \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0935\u093f\u091a\u0932\u0928 \u0906\u0924\u093e \u0939\u0948\u0964\n\n---\n\n## 2. \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u092a\u0943\u0937\u094d\u0920\u092d\u0942\u092e\u093f \u090f\u0935\u0902 \u0924\u0930\u094d\u0915\u093e\u0927\u093e\u0930 (Theoretical Rationale)\n\n1. **\u092c\u0948\u0915\u0935\u0930\u094d\u0921 \u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928 \u0915\u093e \u0935\u093f\u092d\u093e\u091c\u0928 ($B$ \u0914\u0930 $W$):**\n   \u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 1F1B \u092e\u0947\u0902 \u092c\u0948\u0915\u0935\u0930\u094d\u0921 \u092a\u093e\u0938 \u090f\u0915 \u090f\u0915\u0932 \u092c\u094d\u0932\u0949\u0915 $(B+W)$ \u0939\u094b\u0924\u093e \u0939\u0948, \u091c\u093f\u0938\u0938\u0947 \u0928\u094d\u092f\u0942\u0928\u0924\u092e \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u092c\u092c\u0932 \u0930\u0947\u091f $\\frac{p - 1}{m}$ \u0939\u094b\u0924\u093e \u0939\u0948 (\u091c\u0939\u093e\u0901 $p$ \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0938\u094d\u091f\u0947\u091c \u0939\u0948 \u0914\u0930 $m$ \u092e\u093e\u0907\u0915\u094d\u0930\u094b-\u092c\u0948\u091a\u0947\u0938 \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e \u0939\u0948)\u0964  \n   Zero Bubble Pipeline Parallelism \u092c\u0948\u0915\u0935\u0930\u094d\u0921 \u092a\u093e\u0938 \u0915\u094b \u0926\u094b \u092d\u093e\u0917\u094b\u0902 \u092e\u0947\u0902 \u0935\u093f\u092d\u093e\u091c\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948:\n   - **$B$ (Activation Backward / Input Gradient):** \u092f\u0939 \u0915\u094d\u0930\u093f\u091f\u093f\u0915\u0932 \u092a\u093e\u0925 \u092a\u0930 \u0939\u094b\u0924\u093e \u0939\u0948 \u0915\u094d\u092f\u094b\u0902\u0915\u093f \u092a\u0942\u0930\u094d\u0935\u0935\u0930\u094d\u0924\u0940 \u0938\u094d\u091f\u0947\u091c \u0915\u094b \u090f\u0915\u094d\u091f\u093f\u0935\u0947\u0936\u0928 \u0917\u094d\u0930\u0948\u0921\u093f\u090f\u0902\u091f \u0915\u0940 \u0924\u0941\u0930\u0902\u0924 \u0906\u0935\u0936\u094d\u092f\u0915\u0924\u093e \u0939\u094b\u0924\u0940 \u0939\u0948\u0964\n   - **$W$ (Weight Gradient):** \u092f\u0939 \u0915\u094d\u0930\u093f\u091f\u093f\u0915\u0932 \u092a\u093e\u0925 \u092a\u0930 \u0928\u0939\u0940\u0902 \u0939\u094b\u0924\u093e \u0939\u0948 \u0914\u0930 \u0907\u0938\u0947 \u092c\u093e\u0926 \u092e\u0947\u0902 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964\n2. **ZB-2p \u0915\u093e \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u093f\u0902\u0917 \u0924\u0902\u0924\u094d\u0930:**\n   \u091c\u092c `--zero-bubble-max-pending-backward` \u0915\u094b $2p$ \u092a\u0930 \u0938\u0947\u091f \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948, \u0924\u094b \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u0930 \u0915\u0947 \u092a\u093e\u0938 $2p$ \u0924\u0915 \u092a\u0947\u0902\u0921\u093f\u0902\u0917 \u090f\u0915\u094d\u091f\u093f\u0935\u0947\u0936\u0928 \u0930\u0916\u0928\u0947 \u0915\u0940 \u092e\u0947\u092e\u094b\u0930\u0940 \u0905\u0928\u0941\u092e\u0924\u093f \u0939\u094b\u0924\u0940 \u0939\u0948\u0964 \u0911\u091f\u094b\u092e\u0948\u091f\u093f\u0915 \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u093f\u0902\u0917 \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e (MILP/Heuristic) $W$ \u092c\u094d\u0932\u0949\u0915\u094d\u0938 \u0915\u094b \u0935\u0949\u0930\u094d\u092e\u0905\u092a \u0914\u0930 \u0915\u0942\u0932\u0921\u093e\u0909\u0928 \u0915\u0947 \u0916\u093e\u0932\u0940 \u0938\u094d\u0932\u0949\u091f\u094d\u0938 (\u092c\u092c\u0932\u094d\u0938) \u092e\u0947\u0902 \u092d\u0930 \u0926\u0947\u0924\u093e \u0939\u0948, \u091c\u093f\u0938\u0938\u0947 \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u092c\u092c\u0932 \u0936\u0942\u0928\u094d\u092f \u0915\u0947 \u0928\u093f\u0915\u091f \u092a\u0939\u0941\u0901\u091a \u091c\u093e\u0924\u093e \u0939\u0948\u0964\n3. **\u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0935\u093f\u091a\u0932\u0928 \u0915\u093e \u0924\u0930\u094d\u0915\u093e\u0927\u093e\u0930 (Why profile on real GPUs?):**\n   - **\u0938\u0902\u091a\u093e\u0930 \u092c\u0928\u093e\u092e \u0917\u0923\u0928\u093e \u0913\u0935\u0930\u0932\u0948\u092a:** \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0939\u093e\u0930\u094d\u0921\u0935\u0947\u092f\u0930 \u092a\u0930 P2P (Point-to-Point) \u0915\u092e\u094d\u092f\u0942\u0928\u093f\u0915\u0947\u0936\u0928 \u0939\u092e\u0947\u0936\u093e \u0917\u0923\u0928\u093e \u0915\u0947 \u0938\u093e\u0925 $100\\%$ \u0913\u0935\u0930\u0932\u0948\u092a \u0928\u0939\u0940\u0902 \u0939\u094b\u0924\u093e\u0964\n   - **\u0905\u0938\u092e\u092e\u093f\u0924 \u0938\u094d\u091f\u0947\u091c \u0932\u0947\u091f\u0947\u0902\u0938\u0940:** \u092a\u0939\u0932\u0947 \u0938\u094d\u091f\u0947\u091c (Embedding Layer) \u0914\u0930 \u0905\u0902\u0924\u093f\u092e \u0938\u094d\u091f\u0947\u091c (LM Head / Cross-Entropy Loss) \u0915\u0940 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u0928 \u0905\u0935\u0927\u093f \u092e\u0927\u094d\u092f\u0935\u0930\u094d\u0924\u0940 \u091f\u094d\u0930\u093e\u0902\u0938\u092b\u0949\u0930\u094d\u092e\u0930 \u0932\u0947\u092f\u0930\u094d\u0938 \u0938\u0947 \u092d\u093f\u0928\u094d\u0928 \u0939\u094b\u0924\u0940 \u0939\u0948\u0964\n   - **\u0938\u094d\u091f\u094d\u0930\u0940\u092e \u0938\u093f\u0902\u0915\u094d\u0930\u094b\u0928\u093e\u0907\u091c\u093c\u0947\u0936\u0928 \u0913\u0935\u0930\u0939\u0947\u0921:** \u092e\u0932\u094d\u091f\u0940\u092a\u0932 CUDA \u0938\u094d\u091f\u094d\u0930\u0940\u092e\u094d\u0938 ($F, B, W$, \u0914\u0930 Comm) \u0915\u0947 \u092c\u0940\u091a \u0907\u0935\u0947\u0902\u091f \u0938\u093f\u0902\u0915\u094d\u0930\u094b\u0928\u093e\u0907\u091c\u093c\u0947\u0936\u0928 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u092e\u093f\u0932\u0940\u0938\u0947\u0915\u0902\u0921\u094d\u0938 \u091c\u094b\u0921\u093c \u0938\u0915\u0924\u093e \u0939\u0948\u0964\n\n---\n\n## 3. \u092a\u094d\u0930\u093e\u092f\u094b\u0917\u093f\u0915 \u0938\u0947\u091f\u0905\u092a \u090f\u0935\u0902 \u0935\u093f\u0928\u094d\u092f\u093e\u0938 (Experimental Setup)\n\n### \u0915. \u0939\u093e\u0930\u094d\u0921\u0935\u0947\u092f\u0930 \u090f\u0935\u0902 \u0938\u093f\u0938\u094d\u091f\u092e \u0935\u093f\u0928\u094d\u092f\u093e\u0938\n- **\u0928\u094b\u0921 \u0938\u0902\u0930\u091a\u0928\u093e:** 8x NVIDIA A100 (80GB SXM4) \u092f\u093e H100 (80GB), \u091c\u093f\u0938\u092e\u0947\u0902 NVSwitch (NVLink 600\u2013900 GB/s \u092c\u093e\u0908\u0921\u093e\u092f\u0930\u0947\u0915\u094d\u0936\u0928\u0932 \u092c\u0948\u0902\u0921\u0935\u093f\u0921\u094d\u0925) \u0909\u092a\u0932\u092c\u094d\u0927 \u0939\u094b\u0964\n- **\u0907\u0902\u091f\u0930-\u0928\u094b\u0921 \u0938\u0902\u0930\u091a\u0928\u093e (\u0938\u094d\u0915\u0947\u0932\u0947\u092c\u093f\u0932\u093f\u091f\u0940 \u092a\u0930\u0940\u0915\u094d\u0937\u0923 \u0939\u0947\u0924\u0941):** 2x 8-GPU \u0928\u094b\u0921\u094d\u0938, 400 Gbps InfiniBand (HDR/NDR) \u0915\u0947 \u0938\u093e\u0925 ($PP=16$ \u092a\u0930\u0940\u0915\u094d\u0937\u0923 \u0939\u0947\u0924\u0941)\u0964\n- **\u0938\u093f\u0938\u094d\u091f\u092e \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938:**\n  - GPU \u0915\u094d\u0932\u0949\u0915\u094d\u0938 \u0915\u094b \u092b\u093f\u0915\u094d\u0938 \u0915\u0930\u0928\u093e (`nvidia-smi -lgc <freq>`) \u0924\u093e\u0915\u093f \u0925\u0930\u094d\u092e\u0932 \u0925\u094d\u0930\u0949\u091f\u0932\u093f\u0902\u0917 \u0915\u0947 \u0915\u093e\u0930\u0923 \u0917\u0923\u0928\u093e \u0938\u092e\u092f \u092e\u0947\u0902 \u0905\u0938\u094d\u0925\u093f\u0930\u0924\u093e \u0928 \u0906\u090f\u0964\n  - ECC \u0938\u0915\u094d\u0937\u092e, CUDA 12.x, PyTorch 2.x, cuDNN 8.x/9.x\u0964\n\n### \u0916. \u0935\u0930\u094d\u0915\u0932\u094b\u0921 \u0914\u0930 \u092e\u0949\u0921\u0932 \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930\n- **\u092e\u0949\u0921\u0932:** LLaMA \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930 \u0935\u093f\u0928\u094d\u092f\u093e\u0938:\n  - **7B:** 32 \u0932\u0947\u092f\u0930\u094d\u0938, \u0939\u093f\u0921\u0928 \u0938\u093e\u0907\u091c\u093c 4096, 32 \u0939\u0947\u0921\u094d\u0938\u0964\n  - **13B / 70B:** 40 / 80 \u0932\u0947\u092f\u0930\u094d\u0938 (\u0938\u094d\u0915\u0947\u0932\u093f\u0902\u0917 \u0914\u0930 \u092e\u0947\u092e\u094b\u0930\u0940 \u0938\u094d\u091f\u094d\u0930\u0947\u0938 \u091f\u0947\u0938\u094d\u091f\u093f\u0902\u0917 \u0939\u0947\u0924\u0941)\u0964\n- **\u0938\u0940\u0915\u094d\u0935\u0947\u0902\u0938 \u0932\u0947\u0902\u0925 ($s$):** 2048 \u0914\u0930 4096 \u091f\u094b\u0915\u0928\u0964\n- **\u092e\u093e\u0907\u0915\u094d\u0930\u094b-\u092c\u0948\u091a \u0938\u093e\u0907\u091c\u093c ($b$):** 1, 2, 4\u0964\n- **\u0921\u0947\u091f\u093e \u092a\u094d\u0930\u093f\u0938\u093f\u091c\u0928:** BFloat16 / FP16 \u092e\u093f\u0915\u094d\u0938\u094d\u0921 \u092a\u094d\u0930\u093f\u0938\u093f\u091c\u0928 (FlashAttention-2 \u0938\u0915\u094d\u0937\u092e)\u0964\n\n### \u0917. \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0915\u0949\u0928\u094d\u092b\u093c\u093f\u0917\u0930\u0947\u0936\u0928 \u092e\u0948\u091f\u094d\u0930\u093f\u0915\u094d\u0938\n| \u0915\u093e\u0930\u0915 (Factor) | \u092e\u093e\u0928 (Levels) |\n|---|---|\n| **\u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0938\u094d\u091f\u0947\u091c ($p$)** | 4, 8 |\n| **\u092e\u093e\u0907\u0915\u094d\u0930\u094b-\u092c\u0948\u091a \u0938\u0902\u0916\u094d\u092f\u093e ($m$)** | $p, 2p, 4p, 8p$ (\u0909\u0926\u093e. $p=8$ \u0915\u0947 \u0932\u093f\u090f $m \\in \\{8, 16, 32, 64\\}$) |\n| **\u0936\u0947\u0921\u094d\u092f\u0942\u0932 \u092a\u094d\u0930\u0915\u093e\u0930** | 1F1B (Megatron-LM), 1F1B-Interleaved ($v=2$), ZB-1p, **ZB-2p** |\n| **ZB \u0915\u0949\u0928\u094d\u092b\u093c\u093f\u0917\u0930\u0947\u0936\u0928 \u092b\u093c\u094d\u0932\u0948\u0917** | `--zero-bubble-max-pending-backward = 2 * p` |\n\n---\n\n## 4. \u092a\u094d\u0930\u093e\u092f\u094b\u0917\u093f\u0915 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 (Experimental Controls)\n\n1. **\u0938\u094d\u091f\u0947\u091c \u0932\u094b\u0921 \u092c\u0948\u0932\u0947\u0902\u0938\u093f\u0902\u0917 \u0915\u0902\u091f\u094d\u0930\u094b\u0932:**\n   - \u0938\u094d\u091f\u0947\u091c 0 (Embedding) \u0914\u0930 \u0938\u094d\u091f\u0947\u091c $p-1$ (Loss/Logits) \u092e\u0947\u0902 \u0939\u094b\u0928\u0947 \u0935\u093e\u0932\u0947 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u0915\u0902\u092a\u094d\u092f\u0942\u091f \u0915\u094b \u0938\u0902\u0924\u0941\u0932\u093f\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0932\u0947\u092f\u0930 \u090f\u0932\u094b\u0915\u0947\u0936\u0928 \u0915\u094b \u0938\u092e\u093e\u092f\u094b\u091c\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e (\u0909\u0926\u093e. \u092e\u0927\u094d\u092f\u0935\u0930\u094d\u0924\u0940 \u0938\u094d\u091f\u0947\u091c\u0947\u0938 \u092e\u0947\u0902 \u0932\u0947\u092f\u0930\u094d\u0938 \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e $\\lceil L/p \\rceil$ \u0914\u0930 \u092a\u0930\u093f\u0927\u0940\u092f \u0938\u094d\u091f\u0947\u091c\u0947\u0938 \u092e\u0947\u0902 $\\lfloor L/p \\rfloor$ \u0930\u0916\u0928\u093e \u092f\u093e \u0911\u091f\u094b\u092e\u0948\u091f\u093f\u0915 \u092a\u094d\u0930\u094b\u092b\u093e\u0907\u0932\u0930 \u0926\u094d\u0935\u093e\u0930\u093e \u092e\u093e\u092a\u0947 \u0917\u090f \u0938\u091f\u0940\u0915 \u0938\u092e\u092f \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u0930 \u0907\u0928\u092a\u0941\u091f \u0926\u0947\u0928\u093e)\u0964\n2. **\u0935\u0949\u0930\u094d\u092e\u0905\u092a \u0914\u0930 \u092e\u093e\u092a \u091a\u0915\u094d\u0930:**\n   - \u092a\u094d\u0930\u093e\u0930\u0902\u092d\u093f\u0915 5 \u092a\u0941\u0928\u0930\u093e\u0935\u0943\u0924\u094d\u0924\u093f\u092f\u094b\u0902 (iterations) \u0915\u094b CUDA \u0938\u0902\u0926\u0930\u094d\u092d \u0906\u0930\u0902\u092d\u0940\u0915\u0930\u0923 \u0914\u0930 \u092e\u0947\u092e\u094b\u0930\u0940 \u090f\u0932\u094b\u0915\u0947\u091f\u0930 \u0938\u094d\u0925\u093f\u0930\u0940\u0915\u0930\u0923 \u0915\u0947 \u0932\u093f\u090f \u091b\u094b\u0921\u093c \u0926\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n   - \u092c\u093e\u0926 \u0915\u0947 20 \u092a\u0941\u0928\u0930\u093e\u0935\u0943\u0924\u094d\u0924\u093f\u092f\u094b\u0902 \u0915\u093e \u0935\u093f\u0938\u094d\u0924\u0943\u0924 \u091f\u094d\u0930\u0947\u0938 \u092a\u094d\u0930\u094b\u092b\u093e\u0907\u0932 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n3. **\u0915\u092e\u094d\u092f\u0942\u0928\u093f\u0915\u0947\u0936\u0928 \u092b\u0948\u092c\u094d\u0930\u093f\u0915 \u0905\u0932\u0917\u093e\u0935:**\n   - \u0907\u0902\u091f\u094d\u0930\u093e-\u0928\u094b\u0921 (NVLink \u0915\u0947\u0935\u0932) \u0914\u0930 \u0907\u0902\u091f\u0930-\u0928\u094b\u0921 (NVLink + InfiniBand) \u0915\u094b \u0905\u0932\u0917-\u0905\u0932\u0917 \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e \u0924\u093e\u0915\u093f \u0928\u0947\u091f\u0935\u0930\u094d\u0915 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u0915\u0947 \u092a\u094d\u0930\u092d\u093e\u0935 \u0915\u094b \u0905\u0932\u0917 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0947\u0964\n4. **\u092e\u0947\u092e\u094b\u0930\u0940 \u0938\u0941\u0930\u0915\u094d\u0937\u093e (OOM \u092a\u094d\u0930\u093f\u0935\u0947\u0902\u0936\u0928):**\n   - $2p$ \u092a\u0947\u0902\u0921\u093f\u0902\u0917 \u092e\u093e\u0907\u0915\u094d\u0930\u094b-\u092c\u0948\u091a\u0947\u0938 \u0915\u0947 \u0915\u093e\u0930\u0923 \u090f\u0915\u094d\u091f\u093f\u0935\u0947\u0936\u0928 \u092e\u0947\u092e\u094b\u0930\u0940 1F1B \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 \u0926\u094b\u0917\u0941\u0928\u0940 \u0939\u094b \u091c\u093e\u0924\u0940 \u0939\u0948\u0964 \u092f\u0926\u093f \u0915\u093f\u0938\u0940 \u092e\u0949\u0921\u0932 \u092e\u0947\u0902 \u092e\u0947\u092e\u094b\u0930\u0940 \u0938\u0940\u092e\u093e \u092a\u093e\u0930 \u0939\u094b\u0924\u0940 \u0939\u0948, \u0924\u094b \u0938\u0947\u0932\u0947\u0915\u094d\u091f\u093f\u0935 \u090f\u0915\u094d\u091f\u093f\u0935\u0947\u0936\u0928 \u091a\u0947\u0915\u092a\u0949\u0907\u0902\u091f\u093f\u0902\u0917 (SAC) \u0915\u094b \u0938\u092d\u0940 \u0936\u0947\u0921\u094d\u092f\u0942\u0932 \u0935\u093f\u0915\u0932\u094d\u092a\u094b\u0902 \u092e\u0947\u0902 \u0938\u092e\u093e\u0928 \u0930\u0942\u092a \u0938\u0947 \u0932\u093e\u0917\u0942 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n\n---\n\n## 5. \u092e\u093e\u092a\u0928 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 \u0914\u0930 \u092a\u094d\u0930\u094b\u092b\u093e\u0907\u0932\u093f\u0902\u0917 \u0935\u093f\u0927\u093f (Profiling & Metrics)\n\n### \u0915. \u092a\u094d\u0930\u094b\u092b\u093e\u0907\u0932\u093f\u0902\u0917 \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928\n1. **\u0911\u092b\u0932\u093e\u0907\u0928 \u092a\u094d\u0930\u094b\u092b\u093e\u0907\u0932\u093f\u0902\u0917 \u091a\u0930\u0923 (Offline Profiling Stage):**\n   - \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0932\u0947\u092f\u0930 \u0915\u0947 $F$, $B$, \u0914\u0930 $W$ \u0915\u0947 \u0938\u091f\u0940\u0915 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u0928 \u0938\u092e\u092f \u0915\u094b PyTorch Profiler \u0938\u0947 \u092e\u093e\u092a\u0915\u0930 \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u0930 \u0915\u0947 ILP \u0938\u0949\u0932\u094d\u0935\u0930 \u0915\u094b \u0926\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964\n2. **NVTX \u0907\u0902\u0938\u094d\u091f\u094d\u0930\u0941\u092e\u0947\u0902\u091f\u0947\u0936\u0928:**\n   - \u0915\u094b\u0921\u092c\u0947\u0938 \u092e\u0947\u0902 \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u092e\u093e\u0907\u0915\u094d\u0930\u094b-\u092c\u0948\u091a \u0915\u0947 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u0928 \u0915\u094b \u0938\u094d\u092a\u0937\u094d\u091f \u0930\u0942\u092a \u0938\u0947 \u091f\u0948\u0917 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e:\n     - `nvtx.range_push(\"F_m{microbatch}_s{stage}\")`\n     - `nvtx.range_push(\"B_m{microbatch}_s{stage}\")`\n     - `nvtx.range_push(\"W_m{microbatch}_s{stage}\")`\n     - `nvtx.range_push(\"P2P_Send\")` / `nvtx.range_push(\"P2P_Recv\")`\n3. **\u091f\u094d\u0930\u0947\u0938 \u0915\u0948\u092a\u094d\u091a\u0930:**\n   - NVIDIA Nsys CLI (`nsys profile -t cuda,nvtx,osrt --cuda-memory-usage=true`) \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u092a\u0942\u0930\u094d\u0923 \u091f\u093e\u0907\u092e\u0932\u093e\u0907\u0928 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0915\u0930\u0928\u093e\u0964\n\n### \u0916. \u092a\u094d\u0930\u093e\u0925\u092e\u093f\u0915 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938\n\n1. **\u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u092c\u092c\u0932 \u0930\u0947\u091f (Empirical Bubble Rate, $\\beta_{\\text{empirical}}$):**\n   $$\\beta_{\\text{empirical}} = 1 - \\frac{\\sum_{j=1}^{p} \\sum_{i=1}^{m} \\left( T_{F_{i,j}} + T_{B_{i,j}} + T_{W_{i,j}} \\right)}{p \\times T_{\\text{total\\_step}}}$$\n   \u091c\u0939\u093e\u0901 $T_{\\text{total\\_step}}$ \u0907\u091f\u0930\u0947\u0936\u0928 \u0915\u093e \u0915\u0941\u0932 \u0935\u0949\u0932-\u0915\u094d\u0932\u0949\u0915 \u0938\u092e\u092f \u0939\u0948\u0964\n2. **\u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u092c\u0928\u093e\u092e \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0935\u093f\u091a\u0932\u0928 (Schedule Deviation, $\\Delta \\beta$):**\n   $$\\Delta \\beta = \\beta_{\\text{empirical}} - \\beta_{\\text{theoretical}}$$\n   (\u091c\u0939\u093e\u0901 $\\beta_{\\text{theoretical}}$ \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u0930 \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e \u0915\u0947 \u0938\u093f\u092e\u0941\u0932\u0947\u091f\u0930 \u0926\u094d\u0935\u093e\u0930\u093e \u0905\u0928\u0941\u092e\u093e\u0928\u093f\u0924 \u092c\u092c\u0932 \u0930\u0947\u091f \u0939\u0948)\u0964\n3. **\u092c\u092c\u0932 \u0915\u093e \u0918\u091f\u0915 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 (Bubble Breakdown):**\n   \u0915\u0941\u0932 \u0928\u093f\u0937\u094d\u0915\u094d\u0930\u093f\u092f \u0938\u092e\u092f (Idle Time) \u0915\u094b \u0928\u093f\u092e\u094d\u0928\u0932\u093f\u0916\u093f\u0924 \u0936\u094d\u0930\u0947\u0923\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u0935\u093f\u092d\u093e\u091c\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e:\n   - **\u091f\u094d\u0930\u0942 \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u092c\u092c\u0932 ($T_{\\text{pipe\\_idle}}$):** \u0921\u0947\u091f\u093e \u0928\u093f\u0930\u094d\u092d\u0930\u0924\u093e (activation/gradient dependency) \u0915\u0947 \u0915\u093e\u0930\u0923 \u091c\u0940\u092a\u0940\u092f\u0942 \u0915\u093e \u092a\u0942\u0930\u094d\u0923\u0924\u0903 \u0928\u093f\u0937\u094d\u0915\u094d\u0930\u093f\u092f \u0930\u0939\u0928\u093e\u0964\n   - **\u0938\u0902\u091a\u093e\u0930 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u092c\u092c\u0932 ($T_{\\text{comm\\_wait}}$):** P2P \u0915\u092e\u094d\u092f\u0942\u0928\u093f\u0915\u0947\u0936\u0928 \u092a\u0942\u0930\u093e \u0928 \u0939\u094b\u0928\u0947 \u0915\u0947 \u0915\u093e\u0930\u0923 \u092c\u094d\u0932\u0949\u0915 \u0939\u094b\u0928\u093e\u0964\n   - **\u0938\u093f\u0902\u0915\u094d\u0930\u094b\u0928\u093e\u0907\u091c\u093c\u0947\u0936\u0928 \u0935 \u0915\u0930\u094d\u0928\u0947\u0932 \u0932\u0949\u0928\u094d\u091a \u0913\u0935\u0930\u0939\u0947\u0921 ($T_{\\text{sync\\_overhead}}$):** CPU \u0939\u094b\u0938\u094d\u091f \u0921\u093f\u0932\u0947 \u092f\u093e CUDA \u0938\u094d\u091f\u094d\u0930\u0940\u092e \u0938\u093f\u0902\u0915\u094d\u0930\u094b\u0928\u093e\u0907\u091c\u093c\u0947\u0936\u0928\u0964\n4. **\u092a\u0940\u0915 \u092e\u0947\u092e\u094b\u0930\u0940 \u0909\u092a\u092f\u094b\u0917 (Peak Memory Consumption):**\n   \u092a\u094d\u0930\u0924\u093f \u091c\u0940\u092a\u0940\u092f\u0942 \u0905\u0927\u093f\u0915\u0924\u092e \u0906\u0935\u0902\u091f\u093f\u0924 \u092e\u0947\u092e\u094b\u0930\u0940 (GB)\u0964\n\n---\n\n## 6. \u0921\u0947\u091f\u093e \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u092f\u094b\u091c\u0928\u093e (Data Analysis Plan)\n\n1. **\u0924\u0941\u0932\u0928\u093e\u0924\u094d\u092e\u0915 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 (ZB-2p vs. 1F1B vs. 1F1B-Interleaved):**\n   - $m/p$ \u0915\u0947 \u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u0905\u0928\u0941\u092a\u093e\u0924\u094b\u0902 ($1, 2, 4, 8$) \u092a\u0930 \u092c\u092c\u0932 \u0930\u0947\u091f \u0914\u0930 \u0925\u094d\u0930\u0942\u092a\u0941\u091f (TFLOPs/sec per GPU) \u0915\u093e \u092c\u093e\u0930-\u091a\u093e\u0930\u094d\u091f \u0935 \u0932\u093e\u0907\u0928-\u092a\u094d\u0932\u0949\u091f \u0924\u0948\u092f\u093e\u0930 \u0915\u0930\u0928\u093e\u0964\n   - \u092f\u0939 \u091c\u093e\u0901\u091a\u0928\u093e \u0915\u093f \u0915\u094d\u092f\u093e $m \\ge 2p$ \u0939\u094b\u0928\u0947 \u092a\u0930 ZB-2p \u0935\u093e\u0938\u094d\u0924\u0935 \u092e\u0947\u0902 $< 2-3\\%$ \u092c\u092c\u0932 \u0930\u0947\u091f \u0924\u0915 \u092a\u0939\u0941\u0901\u091a\u0924\u093e \u0939\u0948\u0964\n2. **\u0938\u0902\u0935\u0947\u0926\u0928\u0936\u0940\u0932\u0924\u093e \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 (Sensitivity Analysis):**\n   - **\u0915\u092e\u094d\u092f\u0942\u0928\u093f\u0915\u0947\u0936\u0928 \u0913\u0935\u0930\u0939\u0947\u0921 \u092a\u094d\u0930\u092d\u093e\u0935:** \u0907\u0902\u091f\u094d\u0930\u093e-\u0928\u094b\u0921 (\u0909\u091a\u094d\u091a \u092c\u0948\u0902\u0921\u0935\u093f\u0921\u094d\u0925) \u092c\u0928\u093e\u092e \u0907\u0902\u091f\u0930-\u0928\u094b\u0921 (\u0927\u0940\u092e\u0940 \u0932\u0947\u091f\u0947\u0902\u0938\u0940) \u092e\u0947\u0902 $\\Delta \\beta$ \u0915\u0940 \u0935\u0943\u0926\u094d\u0927\u093f \u0926\u0930 \u0915\u093e \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923\u0964\n   - **\u0938\u094d\u091f\u0947\u091c \u0905\u0938\u0902\u0924\u0941\u0932\u0928 \u092a\u094d\u0930\u092d\u093e\u0935:** \u092f\u0926\u093f \u0938\u094d\u091f\u0947\u091c 0 \u0915\u093e $T_F$ \u092e\u0927\u094d\u092f\u0935\u0930\u094d\u0924\u0940 \u0938\u094d\u091f\u0947\u091c\u0947\u0938 \u0938\u0947 $15\\%$ \u0905\u0927\u093f\u0915 \u0939\u0948, \u0924\u094b \u092f\u0939 \u0905\u0938\u092e\u093e\u0928\u0924\u093e \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0915\u0947 \u0905\u0902\u0924\u093f\u092e \u092c\u092c\u0932 \u0930\u0947\u091f \u0915\u094b \u0915\u093f\u0924\u0928\u093e \u092c\u0922\u093c\u093e\u0924\u0940 \u0939\u0948\u0964\n3. **\u0939\u093e\u0907\u092a\u094b\u0925\u0940\u0938\u093f\u0938 \u091f\u0947\u0938\u094d\u091f\u093f\u0902\u0917 (Statistical Hypothesis Testing):**\n   - 20 \u091f\u094d\u0930\u0947\u0938\u094d\u0921 \u0907\u091f\u0930\u0947\u0936\u0902\u0938 \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 $95\\%$ \u0915\u0949\u0928\u094d\u092b\u093f\u0921\u0947\u0902\u0938 \u0907\u0902\u091f\u0930\u0935\u0932 (CI) \u0915\u0940 \u0917\u0923\u0928\u093e\u0964\n   - \u0939\u093e\u0907\u092a\u094b\u0925\u0940\u0938\u093f\u0938 \u091f\u0947\u0938\u094d\u091f:\n     - $H_0: \\beta_{\\text{empirical, ZB-2p}} \\ge 0.05$ (\u0905\u0930\u094d\u0925\u093e\u0924 \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u092c\u092c\u0932 \u0930\u0947\u091f $5\\%$ \u092f\u093e \u0905\u0927\u093f\u0915 \u0930\u0939\u0924\u093e \u0939\u0948)\u0964\n     - $H_a: \\beta_{\\text{empirical, ZB-2p}} < 0.05$ (\u0905\u0930\u094d\u0925\u093e\u0924 ZB-2p \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u0928\u093f\u092f\u0930-\u091c\u0940\u0930\u094b \u092c\u092c\u0932 \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930\u0924\u093e \u0939\u0948)\u0964\n\n---\n\n## 7. \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915\u0924\u093e \u090f\u0935\u0902 \u092a\u0942\u0930\u094d\u0935-\u091c\u093e\u0901\u091a (Feasibility & Sanity Checks)\n\n1. **\u0936\u0947\u0921\u094d\u092f\u0942\u0932 \u0935\u0948\u0927\u0924\u093e \u091c\u093e\u0901\u091a (Schedule Validity Check):**\n   - \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u0930 \u0915\u0947 \u0906\u0909\u091f\u092a\u0941\u091f \u0915\u094b \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u093f\u0924 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 DAG \u0938\u0924\u094d\u092f\u093e\u092a\u0928\u0915\u0930\u094d\u0924\u093e (DAG Validator) \u0926\u094d\u0935\u093e\u0930\u093e \u091c\u093e\u0901\u091a\u0928\u093e \u0915\u093f \u0938\u092d\u0940 \u0921\u0947\u091f\u093e \u0928\u093f\u0930\u094d\u092d\u0930\u0924\u093e\u090f\u0901 (Data Dependencies) \u092a\u0942\u0930\u0940 \u0939\u0948\u0902 (\u0909\u0926\u093e. $B_{i,j}$ \u0939\u092e\u0947\u0936\u093e $F_{i,j}$ \u0915\u0947 \u092c\u093e\u0926 \u0914\u0930 $W_{i,j}$ \u0939\u092e\u0947\u0936\u093e $B_{i,j}$ \u0915\u0947 \u092c\u093e\u0926 \u0939\u0940 \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u094d\u0921 \u0939\u094b)\u0964\n2. **\u092e\u0947\u092e\u094b\u0930\u0940 \u0915\u094d\u0937\u092e\u0924\u093e \u091c\u093e\u0901\u091a:**\n   - 80GB A100/H100 \u092a\u0930 $2p$ \u090f\u0915\u094d\u091f\u093f\u0935\u0947\u0936\u0902\u0938 \u0915\u0947 \u0938\u093e\u0925 LLaMA-7B/13B \u0906\u0938\u093e\u0928\u0940 \u0938\u0947 \u092b\u093f\u091f \u0939\u094b\u0924\u0947 \u0939\u0948\u0902 (\u092a\u094d\u0930\u0924\u093f \u092e\u093e\u0907\u0915\u094d\u0930\u094b-\u092c\u0948\u091a \u0906\u0915\u093e\u0930 1 \u092f\u093e 2 \u0915\u0947 \u0938\u093e\u0925)\u0964 70B \u0915\u0947 \u0932\u093f\u090f \u091f\u0947\u0902\u0938\u0930 \u092a\u0948\u0930\u0947\u0932\u0932\u093f\u091c\u094d\u092e ($TP=2$ \u092f\u093e $4$) \u0915\u094b \u091c\u094b\u0921\u093c\u0915\u0930 \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u092c\u0928\u093e\u0908 \u091c\u093e \u0938\u0915\u0924\u0940 \u0939\u0948\u0964\n3. **\u0915\u092e\u094d\u092f\u0942\u0928\u093f\u0915\u0947\u0936\u0928-\u0915\u0902\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928 \u0921\u0947\u0921\u0932\u0949\u0915 \u092a\u094d\u0930\u093f\u0935\u0947\u0902\u0936\u0928:**\n   - P2P \u0911\u092a\u0930\u0947\u0936\u0902\u0938 \u0915\u0947 \u0932\u093f\u090f \u0917\u0948\u0930-\u092c\u094d\u0932\u0949\u0915\u093f\u0902\u0917 (non-blocking) \u0915\u0949\u0932\u094d\u0938 (`torch.distributed.isend` / `irecv`) \u0914\u0930 \u0938\u092e\u0930\u094d\u092a\u093f\u0924 \u0915\u092e\u094d\u092f\u0942\u0928\u093f\u0915\u0947\u0936\u0928 \u0938\u094d\u091f\u094d\u0930\u0940\u092e\u094d\u0938 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0938\u0941\u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u0915\u0930\u0928\u093e\u0964\n\n---\n\n## 8. \u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937 (Expected Deliverables)\n\n\u0907\u0938 \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0915\u0947 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u0928 \u0938\u0947 \u0928\u093f\u092e\u094d\u0928\u0932\u093f\u0916\u093f\u0924 \u0920\u094b\u0938 \u092a\u0930\u093f\u0923\u093e\u092e \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0939\u094b\u0902\u0917\u0947:\n- \u0938\u094d\u092a\u0937\u094d\u091f \u092a\u094d\u0930\u092e\u093e\u0923 \u0915\u093f \u0915\u093f\u0928 \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u092a\u0930\u093f\u0938\u094d\u0925\u093f\u0924\u093f\u092f\u094b\u0902 (\u0909\u0926\u093e. \u092a\u0930\u094d\u092f\u093e\u092a\u094d\u0924 $m/p$ \u0905\u0928\u0941\u092a\u093e\u0924 \u0914\u0930 \u0909\u091a\u094d\u091a-\u092c\u0948\u0902\u0921\u0935\u093f\u0921\u094d\u0925 NVLink) \u092e\u0947\u0902 ZB-2p \u0935\u093e\u0938\u094d\u0924\u0935 \u092e\u0947\u0902 \u0928\u093f\u092f\u0930-\u091c\u0940\u0930\u094b \u092c\u092c\u0932 (<3%) \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930\u0924\u093e \u0939\u0948\u0964\n- \u0935\u0947 \u092a\u094d\u0930\u092e\u0941\u0916 \u0939\u093e\u0930\u094d\u0921\u0935\u0947\u092f\u0930 \u0914\u0930 \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930\u0932 \u092c\u093e\u0927\u093e\u090f\u0901 (\u091c\u0948\u0938\u0947 P2P \u0938\u093f\u0902\u0915\u094d\u0930\u094b\u0928\u093e\u0907\u091c\u093c\u0947\u0936\u0928 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u0914\u0930 \u0938\u094d\u091f\u0947\u091c \u0932\u094b\u0921 \u0905\u0938\u0902\u0924\u0941\u0932\u0928) \u091c\u094b \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0936\u0942\u0928\u094d\u092f \u092c\u092c\u0932 \u0915\u094b \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u0935\u093f\u091a\u0932\u093f\u0924 \u0915\u0930\u0924\u0940 \u0939\u0948\u0902\u0964", "evidence": "\u091f\u093e\u0938\u094d\u0915 \u0935\u093f\u0928\u093f\u0930\u094d\u0926\u0947\u0936 (`task.json` \u090f\u0935\u0902 `track.md`) \u092e\u0947\u0902 \u0938\u094d\u092a\u0937\u094d\u091f \u0939\u0948 \u0915\u093f \u0930\u093f\u092a\u0949\u091c\u093f\u091f\u0930\u0940 \u0